/**
 * Novus OS - update trust anchors (cabundle).
 *
 * Generated by tools/cabundle/import_roots.py + cabundle.py from
 * tools/cabundle/roots.pem, the checked-in set of real vendor roots
 * (Debian/Mozilla CA program, curl CA bundle, ICANN, ISRG). See roots.pem
 * for the full source and license list. Empty by default so SYS_HTTPS
 * fails closed.
 *
 * The set is a flat DER blob plus parallel offset/length tables. The kernel
 * references the blob in place (.rodata); it never copies the ~170 KB into
 * BSS. NOVUS_CABUNDLE_MAX mirrors NET_HTTP_MAX_ROOTS.
 */
#ifndef NOVUS_CABUNDLE_H
#define NOVUS_CABUNDLE_H

#include "novu_format.h"

#define NOVUS_CABUNDLE_MAX 192u

extern const UINT8 novus_cabundle_der[];
extern const UINT32 novus_cabundle_len;       /* total DER bytes in the blob */
extern const UINT32 novus_cabundle_count;     /* number of roots */
extern const UINT32 novus_cabundle_off[];     /* offset of each root */
extern const UINT32 novus_cabundle_root_len[];/* length of each root */

/* QEMU-only test anchor (security/novu/cabundle_e2e.c), linked only when
 * E2E=1. Never present in a production image. */
#if NOVUS_HTTPS_E2E_PROBE
extern const UINT8 novus_e2e_root_der[];
extern const UINT32 novus_e2e_root_len;
#endif

#endif /* NOVUS_CABUNDLE_H */
